    #[invariant]
    pub fn inv_request_ids_finite(&self) -> bool {
        &&& self.local_reads.dom().finite()
        &&& self.local_updates.dom().finite()
        &&& self.combiner.dom().finite()
    }

    // /// there must be a replicat for all nodes
    // #[invariant]
    // pub fn inv_replicas_complete(&self) -> bool {
